engine.buildBionicHtml:
function buildBionicHtml(text, fixationPercent) {
  if (!text || typeof text !== "string") return { html: "", wordCount: 0 };
  var pct = Math.max(10, Math.min(80, Number(fixationPercent) || 40));
  var words = text.split(/(\s+)/);
  var wordCount = 0;
  var parts = words.map(function (word) {
    if (/^\s+$/.test(word)) return word;
    // Strip trailing punctuation so it stays unbolded.
    var match = word.match(/^([a-zA-Z0-9''-]+)([^a-zA-Z0-9]*)$/);
    if (!match) return word;
    var mainWord = match[1];
    var punctuation = match[2] || "";
    if (!mainWord) return word;
    wordCount++;
    var boldLen = Math.max(1, Math.ceil(mainWord.length * (pct / 100)));
    var boldPart = mainWord.substring(0, boldLen);
    var regularPart = mainWord.substring(boldLen);
    return '<span style="font-weight:bold;">' + boldPart + '</span><span>' + regularPart + '</span>' + punctuation;
  });
  return { html: parts.join(""), wordCount: wordCount };
}

view.renderFocusFlowUI:
function renderFocusFlowUI(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  opts = opts || {};
  var mount = opts.mount;
  if (!mount) return null;
  var onApply  = opts.onApply  || function () {};
  var onRevert = opts.onRevert || function () {};
  var onHome   = opts.onHome   || function () {};

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_ff_root";

  // Header bar — dark navy + gold accent, matches the v3 tool-hub
  // header style (same as build_draft/legal_risks).
  root.innerHTML =
    '<div class="_eli3_ff_bar">' +
      '<button type="button" class="_eli3_ff_back" title="Back">←</button>' +
      '<div class="_eli3_ff_title">👁️ Focus Flow</div>' +
      '<div class="_eli3_ff_overview">BIONIC READING</div>' +
    '</div>' +
    '<div class="_eli3_ff_body">' +
      '<div class="_eli3_ff_intro">' +
        'Bionic reading bolds the first N% of each word so your eye anchors faster. ' +
        'Apply across the whole document, adjust intensity, or revert when done.' +
      '</div>' +
      '<div class="_eli3_ff_card">' +
        '<div class="_eli3_ff_card_header">' +
          '<span class="_eli3_ff_card_label">FIXATION INTENSITY</span>' +
          '<span class="_eli3_ff_card_value" id="_eli3_ff_value">40%</span>' +
        '</div>' +
        '<input type="range" class="_eli3_ff_slider" id="_eli3_ff_slider" min="10" max="80" step="10" value="40">' +
        '<div class="_eli3_ff_slider_legend">' +
          '<span>10% (subtle)</span>' +
          '<span>80% (max)</span>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_ff_actions">' +
        '<button type="button" class="_eli3_ff_apply" id="_eli3_ff_apply">🚀 APPLY FAST BOLDING</button>' +
        '<button type="button" class="_eli3_ff_revert" id="_eli3_ff_revert">↺ REVERT ALL BOLD</button>' +
      '</div>' +
    '</div>';
  mount.appendChild(root);

  var slider = root.querySelector("#_eli3_ff_slider");
  var valueLbl = root.querySelector("#_eli3_ff_value");
  var applyBtn = root.querySelector("#_eli3_ff_apply");
  var revertBtn = root.querySelector("#_eli3_ff_revert");
  var backBtn = root.querySelector("._eli3_ff_back");

  slider.oninput = function () { valueLbl.textContent = slider.value + "%"; };

  applyBtn.onclick = function () {
    var pct = parseInt(slider.value, 10);
    applyBtn.disabled = true;
    revertBtn.disabled = true;
    applyBtn.textContent = "⏳ Applying…";
    Promise.resolve(onApply(pct)).then(function (res) {
      applyBtn.disabled = false;
      revertBtn.disabled = false;
      if (res && res.ok) {
        applyBtn.textContent = "✅ APPLIED · " + (res.wordCount || 0) + " WORDS";
        setTimeout(function () { applyBtn.textContent = "🚀 APPLY FAST BOLDING"; }, 2500);
      } else {
        applyBtn.textContent = "❌ APPLY FAILED";
        setTimeout(function () { applyBtn.textContent = "🚀 APPLY FAST BOLDING"; }, 2500);
      }
    }).catch(function () {
      applyBtn.disabled = false;
      revertBtn.disabled = false;
      applyBtn.textContent = "❌ APPLY FAILED";
      setTimeout(function () { applyBtn.textContent = "🚀 APPLY FAST BOLDING"; }, 2500);
    });
  };

  revertBtn.onclick = function () {
    applyBtn.disabled = true;
    revertBtn.disabled = true;
    revertBtn.textContent = "⏳ Reverting…";
    Promise.resolve(onRevert()).then(function () {
      applyBtn.disabled = false;
      revertBtn.disabled = false;
      revertBtn.textContent = "✅ REVERTED";
      setTimeout(function () { revertBtn.textContent = "↺ REVERT ALL BOLD"; }, 2000);
    }).catch(function () {
      applyBtn.disabled = false;
      revertBtn.disabled = false;
      revertBtn.textContent = "↺ REVERT ALL BOLD";
    });
  };

  backBtn.onclick = onHome;

  return { refresh: function () {} };
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["focus_flow"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var buildBionicHtml   = efns.buildBionicHtml;
  var renderFocusFlowUI = vfns.renderFocusFlowUI;
  if (!buildBionicHtml || !renderFocusFlowUI) {
    eli.log.event("tool", "focus_flow_load_failed", {
      hasEngine: !!buildBionicHtml, hasView: !!renderFocusFlowUI,
    });
    return;
  }

  // ─── Tile handler ────────────────────────────────────────────────
  function _open() {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) {
      if (typeof showToast === "function") showToast("Dashboard root missing — try reopening ELI", "err");
      return;
    }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedFocusFlow"); } catch (e) {}
    try {
      if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") {
        eli.fsm.transition("rendering");
      }
    } catch (e) {}
    renderFocusFlowUI({
      mount: mount,
      onApply: function (pct) { return _applyBionic(pct); },
      onRevert: function () { return _revertBionic(); },
      onHome: function () {
        try { eli.fsm.transition("idle"); } catch (e) {}
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
        else if (typeof showHome === "function") showHome();
      },
    });
  }

  // ─── Apply bionic bolding ────────────────────────────────────────
  // Iterates paragraphs, computes bionic HTML per paragraph (engine),
  // and replaces via insertHtml. Suppresses track-changes during the
  // apply so the redline pane isn't flooded with formatting deltas.
  // FROM v2 executeBionicBoldingFast.
  function _applyBionic(pct) {
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.resolve({ ok: false });
    }
    if (typeof showToast === "function") showToast("⏳ Applying bionic bolding…", "info");
    return eli.host.runRaw("focus_flow:apply", function (context) {
      var doc = context.document;
      var prevTracking = null;
      try { prevTracking = doc.changeTrackingMode; } catch (e) {}
      try { doc.changeTrackingMode = "Off"; } catch (e) {}
      var paragraphs = doc.body.paragraphs;
      paragraphs.load("items");
      return context.sync().then(function () {
        // Phase 1: load text for all paragraphs in one batch.
        for (var i = 0; i < paragraphs.items.length; i++) {
          paragraphs.items[i].load("text");
        }
        return context.sync();
      }).then(function () {
        // Phase 2: per-paragraph bionic HTML insert. Keep each Word
        // operation under the 100ms keystone budget by chunking via
        // micro-syncs every N paragraphs.
        var totalWords = 0;
        var chunkSize = 25;
        var chain = Promise.resolve();
        for (var i = 0; i < paragraphs.items.length; i++) {
          (function (idx) {
            chain = chain.then(function () {
              var para = paragraphs.items[idx];
              var text = para.text;
              if (!text || text.trim().length <= 1) return null;
              var result = buildBionicHtml(text, pct);
              if (!result.html) return null;
              totalWords += result.wordCount;
              para.insertHtml(result.html, "Replace");
              if ((idx + 1) % chunkSize === 0) return context.sync();
              return null;
            });
          })(i);
        }
        return chain.then(function () {
          return context.sync().then(function () {
            if (prevTracking) {
              try { doc.changeTrackingMode = prevTracking; } catch (e) {}
            }
            return { ok: true, wordCount: totalWords };
          });
        });
      });
    }).then(function (res) {
      if (res && res.ok) {
        if (typeof showToast === "function") {
          showToast("✅ Applied bionic bolding · " + res.wordCount + " words", "ok");
        }
        // Stats + quirky trophy.
        try { if (eli.stats && eli.stats.record) eli.stats.record("bionicWords", res.wordCount); } catch (e) {}
        try {
          eli.dispatch && eli.dispatch("trophies", "unlocked", {
            id: "focus_flow",
            icon: "👁️",
            title: "Bionic Reader",
            desc: "Applied bionic bolding to a document.",
          });
        } catch (e) {}
      } else {
        if (typeof showToast === "function") showToast("Apply failed", "err");
      }
      return res;
    }).catch(function (e) {
      eli.log.event("tool", "focus_flow_apply_failed", { msg: e && e.message });
      if (typeof showToast === "function") {
        showToast("Apply failed: " + (e && e.message || "unknown"), "err");
      }
      return { ok: false };
    });
  }

  // ─── Revert all bold ────────────────────────────────────────────
  // Body-wide font.bold = false. Caveat: removes ALL bolding (including
  // intentional headings) — v2 had the same behavior. Document warns
  // users in the UI.
  function _revertBionic() {
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.resolve({ ok: false });
    }
    if (typeof showToast === "function") showToast("⏳ Reverting bold formatting…", "info");
    return eli.host.runRaw("focus_flow:revert", function (context) {
      var doc = context.document;
      var prevTracking = null;
      try { prevTracking = doc.changeTrackingMode; } catch (e) {}
      try { doc.changeTrackingMode = "Off"; } catch (e) {}
      doc.body.font.bold = false;
      return context.sync().then(function () {
        if (prevTracking) {
          try { doc.changeTrackingMode = prevTracking; } catch (e) {}
        }
        return { ok: true };
      });
    }).then(function () {
      if (typeof showToast === "function") showToast("✅ Document restored to normal", "ok");
      return { ok: true };
    }).catch(function (e) {
      eli.log.event("tool", "focus_flow_revert_failed", { msg: e && e.message });
      if (typeof showToast === "function") {
        showToast("Revert failed: " + (e && e.message || "unknown"), "err");
      }
      return { ok: false };
    });
  }

  // ─── Channels ────────────────────────────────────────────────────
  eli.register({
    tile: { app_focus_flow: _open, "focus-flow": _open },
    focus_flow: { open: _open },
  });

  // Back-compat: v2 catalog action calls `showFocusFlowUI` as a global.
  // Shim it for any cross-tool callers still using the v2 name.
  window.showFocusFlowUI = _open;

  eli.log.event("tool", "focus_flow_initialized", {});
}

jsonTools.css:
/* tools/focus_flow/style.css — FocusFlow control panel.
   Matches the v3 tool-hub layout (dark navy bar, gold accent,
   centered card). Injected as <style data-tool="focus_flow">. */

._eli3_ff_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
  box-sizing: border-box;
}

/* Standard tool-hub header — matches build_draft / legal_risks. */
._eli3_ff_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_ff_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_ff_back:hover { color: #f2d866; }
._eli3_ff_title {
  flex: 1;
  font: 800 16px/1.2 'Georgia', serif;
  color: #ffffff;
  letter-spacing: 0.2px;
}
._eli3_ff_overview {
  font: 700 9px/1 'Inter', sans-serif;
  letter-spacing: 1px;
  color: #e5cc80;
  text-transform: uppercase;
}

._eli3_ff_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 18px 16px;
  display: flex; flex-direction: column;
  gap: 16px;
}
._eli3_ff_intro {
  font: 400 12px/1.5 'Inter', sans-serif;
  color: #475569;
}

/* Settings card — single intensity slider with header + legend. */
._eli3_ff_card {
  background: linear-gradient(180deg, #f0f7ff 0%, #e3f2fd 100%);
  border-left: 5px solid #1565c0;
  padding: 14px 16px;
  display: flex; flex-direction: column;
  gap: 8px;
}
._eli3_ff_card_header {
  display: flex; justify-content: space-between; align-items: center;
}
._eli3_ff_card_label {
  font: 800 10px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #1565c0;
}
._eli3_ff_card_value {
  font: 800 16px/1 'Inter', sans-serif;
  color: #1565c0;
  font-variant-numeric: tabular-nums;
}
._eli3_ff_slider {
  width: 100%;
  cursor: pointer;
  accent-color: #1565c0;
}
._eli3_ff_slider_legend {
  display: flex; justify-content: space-between;
  font: 500 10px/1 'Inter', sans-serif;
  color: #64748b;
  margin-top: 2px;
}

/* Apply + Revert actions. Apply is the bold blue primary, Revert is
   the platinum-style secondary in red. */
._eli3_ff_actions {
  display: flex; flex-direction: column;
  gap: 10px;
}
._eli3_ff_apply {
  width: 100%;
  padding: 14px;
  font: 800 12px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: none;
  cursor: pointer;
  transition: box-shadow 0.15s;
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.3);
}
._eli3_ff_apply:hover:not(:disabled) { box-shadow: 0 6px 18px rgba(21, 101, 192, 0.45); }
._eli3_ff_apply:disabled { opacity: 0.55; cursor: not-allowed; box-shadow: none; }

._eli3_ff_revert {
  width: 100%;
  padding: 12px;
  font: 800 11px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  background: #fff;
  color: #c62828;
  border: 1px solid #ef9a9a;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
._eli3_ff_revert:hover:not(:disabled) { background: #ffebee; border-color: #c62828; }
._eli3_ff_revert:disabled { opacity: 0.55; cursor: not-allowed; }

/* Light/dark mode neutral — panel stays white in both. */
